{
    public static bool operator ==(Weird? a, Weird? b) => true;
    public static bool operator !=(Weird? a, Weird? b) => false;
}

Weird w = new();
Console.WriteLine(w == null);   // True — так решил оператор
Console.WriteLine(w is null);   // False — честная проверка

