var c = new Celsius(100);
var f1 = (Fahrenheit)c;          // оператор: 212
object o = c;
var f2 = (Fahrenheit)o;          // InvalidCastException

readonly record struct Celsius(double V);
readonly record struct Fahrenheit(double V)
{
    public static explicit operator Fahrenheit(Celsius c) => new(c.V * 9 / 5 + 32);
}
